int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> arr(n);
    for (long long &x : arr) cin >> x;

    for (int i = 0; i < n; ++i) {
        long long mn, mx;

        if (i == 0) mn = arr[1] - arr[0];
        else if (i == n - 1) mn = arr[n - 1] - arr[n - 2];
        else mn = min(arr[i] - arr[i - 1], arr[i + 1] - arr[i]);

        mx = max(arr[i] - arr[0], arr[n - 1] - arr[i]);

        cout << mn << ' ' << mx << '\n';
    }

    return 0;
}

