int main() {
    int n;
    scanf("%d", &n);

    vector<ll> arr(n);
    for (ll &x : arr) scanf("%lld", &x);

    for (int i = 0; i < n; ++i) {
        ll mn, mx;

        if (n == 1) {
            mn = mx = 0;
        } else {
            if (i == 0)
                mn = arr[1] - arr[0];
            else if (i == n - 1)
                mn = arr[n - 1] - arr[n - 2];
            else
                mn = min(arr[i] - arr[i - 1], arr[i + 1] - arr[i]);

            mx = max(arr[i] - arr[0], arr[n - 1] - arr[i]);
        }

        printf("%lld %lld\n", mn, mx);
    }

    return 0;
}

